std::string text = "ID-1234: Data";
std::regex pat("(\\d+)");
std::smatch match;

if (std::regex_search(text, match, pat)) {
    // 1. Full Match:
    std::string full = match.str(0);

    // 2. Sub-match (Group 1):
    std::string group = match.str(1);

    // 3. Prefix (Before match):
    std::string prefix = match.prefix().str(); // "ID-"

    // 4. Suffix (After match):
    std::string suffix = match.suffix().str(); // ": Data"

    // Sub-match context access (ssub_match):
    auto& sub = match[1];
    int length = sub.length();
}
